CREATE OR REPLACE FUNCTION mangaro_private.cloud_novel_position(source text, value jsonb, chapter_url text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare entry jsonb;
begin
 if value is null or value='null'::jsonb then return true; end if;
 if jsonb_typeof(value)<>'object' or value - array['chapter','paragraph','offset','updatedAt','anchor']::text[] <> '{}'::jsonb then return false; end if;
 if jsonb_typeof(value->'chapter') is distinct from 'object' then return false; end if;
 if (value->'chapter') - array['url','title','order','volume','volumeId','sourcePage','available','publishedRows','unavailableReason','sunovelsState','sunovelsEvidence']::text[] <> '{}'::jsonb then return false; end if;
 if not mangaro_private.cloud_novel_url(source,value->'chapter'->>'url') or
   (chapter_url is not null and value->'chapter'->>'url' is distinct from chapter_url) then return false; end if;
 if jsonb_typeof(value->'chapter'->'title') is distinct from 'string' or char_length(value->'chapter'->>'title')>512 then return false; end if;
 if jsonb_typeof(value->'chapter'->'order') is distinct from 'number' then return false; end if;
 if (value ? 'paragraph' and jsonb_typeof(value->'paragraph')<>'number') or
   (value ? 'offset' and jsonb_typeof(value->'offset')<>'number') or
   (value ? 'updatedAt' and jsonb_typeof(value->'updatedAt')<>'number') then return false; end if;
 if coalesce(value->'chapter'->>'order','') !~ '^[0-9]{1,7}$' then return false; end if;
 if coalesce(value->>'paragraph','0') !~ '^[0-9]{1,7}$' or coalesce(value->>'offset','0') !~ '^[0-9]{1,8}$' or
   coalesce(value->>'updatedAt','0') !~ '^[0-9]{1,16}$' then return false; end if;
 if (value->'chapter'->>'order')::bigint>1000000 then return false; end if;
 if coalesce((value->>'paragraph')::bigint,0)>1000000 or coalesce((value->>'offset')::bigint,0)>10000000 then return false; end if;
 if value ? 'anchor' and (jsonb_typeof(value->'anchor')<>'string' or char_length(value->>'anchor')>4096) then return false; end if;
 -- Old accepted APKs can include these bounded chapter metadata fields; none grant reader access.
 if value->'chapter' ? 'sunovelsState' and value->'chapter'->>'sunovelsState' not in ('INDEXED_UNVERIFIED','VERIFIED_READABLE','EXPLICITLY_LOCKED','AMBIGUOUS','MISSING','TEMPORARILY_UNAVAILABLE') then return false; end if;
 if value->'chapter' ? 'sunovelsEvidence' and value->'chapter'->>'sunovelsEvidence' not in ('INDEX','PUBLIC_READER','TRANSPORT') then return false; end if;
 if value->'chapter' ? 'publishedRows' and (jsonb_typeof(value->'chapter'->'publishedRows')<>'array' or jsonb_array_length(value->'chapter'->'publishedRows')>200) then return false; end if;
 if value->'chapter' ? 'unavailableReason' and (jsonb_typeof(value->'chapter'->'unavailableReason')<>'string' or char_length(value->'chapter'->>'unavailableReason')>1024) then return false; end if;
 if value->'chapter' ? 'available' and jsonb_typeof(value->'chapter'->'available')<>'boolean' then return false; end if;
 for entry in select * from jsonb_array_elements(coalesce(value->'chapter'->'publishedRows','[]'::jsonb)) loop
  if jsonb_typeof(entry)<>'object' or entry-array['url','title','publishedAt']::text[]<>'{}'::jsonb
   or not mangaro_private.cloud_novel_url(source,entry->>'url')
   or jsonb_typeof(entry->'title') is distinct from 'string' or char_length(entry->>'title')>512
   or (entry ? 'publishedAt' and entry->'publishedAt'<>'null'::jsonb and (jsonb_typeof(entry->'publishedAt')<>'string' or char_length(entry->>'publishedAt')>128)) then return false; end if;
 end loop;


 return true;
end; $function$
